python3 -c "
import json

dr_def = json.load(open('/tmp/dr.json'))
en_def = json.load(open('/tmp/en.json'))

# Get the existing trigger definition from the scaffolded flow
existing = json.load(open('/work/output/artifacts/skill-flow-summarize/SummarizeDemo/SummarizeDemo/SummarizeDemo.flow'))
trigger_def = existing['definitions'][0]  # core.trigger.manual

flow = {
  'id': existing['id'],
  'version': existing['version'],
  'name': 'SummarizeDemo',
  'nodes': [
    {
      'id': 'start',
      'type': 'core.trigger.manual',
      'typeVersion': '1.0',
      'display': { 'label': 'Manual trigger' },
      'inputs': existing['nodes'][0]['inputs']  # preserve entryPointId + isDefaultEntryPoint
    },
    {
      'id': 'summarizeDoc',
      'type': 'uipath.pattern.deep-rag',
      'typeVersion': '1.0',
      'display': { 'label': 'Summarize Document' },
      'inputs': {
        'attachment': '=js:\$vars.start.output.documentFile',
        'prompt': 'Write a 5-bullet executive summary covering scope, term, SLAs, penalties, and termination.',
        'returnCitations': True
      },
      'outputs': {
        'output': {
          'type': 'object',
          'source': '=response',
          'var': 'output',
          'schema': {
            '\$schema': 'http://json-schema.org/draft-07/schema#',
            'type': 'object',
            'properties': {
              'id': { 'type': 'string' },
              'content': {
                'type': ['object', 'null'],
                'properties': {
                  'Text': { 'type': 'string' },
                  'Citations': {
                    'type': ['array', 'null'],
                    'items': {
                      'type': 'object',
                      'properties': {
                        'Ordinal':    { 'type': 'integer' },
                        'PageNumber': { 'type': 'integer' },
                        'Source':     { 'type': 'string' },
                        'Reference':  { 'type': 'string' }
                      }
                    }
                  }
                }
              }
            }
          }
        },
        'error': {
          'type': 'object',
          'description': 'Error information if the node fails',
          'source': '=Error',
          'var': 'error'
        }
      }
    },
    {
      'id': 'end',
      'type': 'core.control.end',
      'typeVersion': '1.0',
      'display': { 'label': 'End' },
      'outputs': {
        'summary':   { 'source': '=js:\$vars.summarizeDoc.output.content.Text' },
        'citations': { 'source': '=js:\$vars.summarizeDoc.output.content.Citations' }
      }
    }
  ],
  'edges': [
    {
      'id': 'edge-start-summarize',
      'sourceNodeId': 'start',
      'sourcePort': 'output',
      'targetNodeId': 'summarizeDoc',
      'targetPort': 'input'
    },
    {
      'id': 'edge-summarize-end',
      'sourceNodeId': 'summarizeDoc',
      'sourcePort': 'output',
      'targetNodeId': 'end',
      'targetPort': 'input'
    }
  ],
  'definitions': [
    trigger_def,
    dr_def,
    en_def
  ],
  'variables': {
    'globals': [
      {
        'id': 'documentFile',
        'direction': 'in',
        'type': 'file',
        'triggerNodeId': 'start'
      },
      {
        'id': 'summary',
        'direction': 'out',
        'type': 'string'
      },
      {
        'id': 'citations',
        'direction': 'out',
        'type': 'array'
      }
    ]
  },
  'layout': {
    'nodes': {
      'start':        { 'position': { 'x': 0,   'y': 0 }, 'size': { 'width': 96, 'height': 96 }, 'collapsed': False },
      'summarizeDoc': { 'position': { 'x': 0,   'y': 0 }, 'size': { 'width': 96, 'height': 96 }, 'collapsed': False },
      'end':          { 'position': { 'x': 0,   'y': 0 }, 'size': { 'width': 96, 'height': 96 }, 'collapsed': False }
    }
  }
}

with open('/work/output/artifacts/skill-flow-summarize/SummarizeDemo/SummarizeDemo/SummarizeDemo.flow', 'w') as f:
    json.dump(flow, f, indent=2)

print('Written successfully')
print('Node IDs:', [n['id'] for n in flow['nodes']])
print('Edge count:', len(flow['edges']))
print('Definitions:', [d['nodeType'] for d in flow['definitions']])
print('Variables:', [v['id'] for v in flow['variables']['globals']])
" 2>&1

